pub const fn decode_tess_output_primitive(opcode_token0: u32) -> u32 {
    (opcode_token0 & D3D11_SB_TESS_OUTPUT_PRIMITIVE_MASK) >> D3D11_SB_TESS_OUTPUT_PRIMITIVE_SHIFT
}
pub const fn encode_tess_output_primitive(output_primitive: u32) -> u32 {
    output_primitive << D3D11_SB_TESS_OUTPUT_PRIMITIVE_SHIFT & D3D11_SB_TESS_OUTPUT_PRIMITIVE_MASK
}
pub const fn decode_instruction_return_type(opcode_token0: u32) -> u32 {
    (opcode_token0 & D3D10_SB_INSTRUCTION_RETURN_TYPE_MASK)
        >> D3D10_SB_INSTRUCTION_RETURN_TYPE_SHIFT
}
pub const fn encode_instruction_return_type(return_type: u32) -> u32 {
    return_type << D3D10_SB_INSTRUCTION_RETURN_TYPE_SHIFT & D3D10_SB_INSTRUCTION_RETURN_TYPE_MASK
}
pub const fn decode_interface_indexed_bit(opcode_token0: u32) -> bool {
    (opcode_token0 & D3D11_SB_INTERFACE_INDEXED_BIT_MASK) >> D3D11_SB_INTERFACE_INDEXED_BIT_SHIFT
        != 0
}
pub const fn encode_interface_indexed_bit(indexed_bit: u32) -> u32 {
    indexed_bit << D3D11_SB_INTERFACE_INDEXED_BIT_SHIFT & D3D11_SB_INTERFACE_INDEXED_BIT_MASK
}
pub const fn decode_interface_table_length(opcode_token0: u32) -> u32 {
    (opcode_token0 & D3D11_SB_INTERFACE_TABLE_LENGTH_MASK) >> D3D11_SB_INTERFACE_TABLE_LENGTH_SHIFT
}
pub const fn encode_interface_table_length(table_length: u32) -> u32 {
    table_length << D3D11_SB_INTERFACE_TABLE_LENGTH_SHIFT & D3D11_SB_INTERFACE_TABLE_LENGTH_MASK
}
pub const fn decode_interface_array_length(opcode_token0: u32) -> u32 {
    (opcode_token0 & D3D11_SB_INTERFACE_ARRAY_LENGTH_MASK) >> D3D11_SB_INTERFACE_ARRAY_LENGTH_SHIFT
}
pub const fn encode_interface_array_length(array_length: u32) -> u32 {
    array_length << D3D11_SB_INTERFACE_ARRAY_LENGTH_SHIFT & D3D11_SB_INTERFACE_ARRAY_LENGTH_MASK
}
pub const fn decode_access_coherency_flags(operand_token0: u32) -> u32 {
    operand_token0 & D3D11_SB_ACCESS_COHERENCY_MASK
}
pub const fn encode_access_coherency_flags(flags: u32) -> u32 {
    flags & D3D11_SB_ACCESS_COHERENCY_MASK
}
pub const fn decode_resource_flags(operand_token0: u32) -> u32 {
    operand_token0 & D3D11_SB_RESOURCE_FLAGS_MASK
}
pub const fn encode_resource_flags(flags: u32) -> u32 {
    flags & D3D11_SB_RESOURCE_FLAGS_MASK
}
pub const fn decode_uav_flags(operand_token0: u32) -> u32 {
    operand_token0 & D3D11_SB_UAV_FLAGS_MASK
}
pub const fn encode_uav_flags(flags: u32) -> u32 {
    flags & D3D11_SB_UAV_FLAGS_MASK
}
pub const fn declaration_has_operand(opcode: u32) -> Option<bool> {
    match opcode {
        D3D10_SB_OPCODE_DCL_RESOURCE
        | D3D10_SB_OPCODE_DCL_CONSTANT_BUFFER
        | D3D10_SB_OPCODE_DCL_SAMPLER
        | D3D10_SB_OPCODE_DCL_INDEX_RANGE
        | D3D10_SB_OPCODE_DCL_INPUT
        | D3D10_SB_OPCODE_DCL_INPUT_SGV
        | D3D10_SB_OPCODE_DCL_INPUT_SIV
        | D3D10_SB_OPCODE_DCL_INPUT_PS
        | D3D10_SB_OPCODE_DCL_INPUT_PS_SGV
        | D3D10_SB_OPCODE_DCL_INPUT_PS_SIV
        | D3D10_SB_OPCODE_DCL_OUTPUT
        | D3D10_SB_OPCODE_DCL_OUTPUT_SGV
        | D3D10_SB_OPCODE_DCL_OUTPUT_SIV
        | D3D11_SB_OPCODE_DCL_STREAM
        | D3D11_SB_OPCODE_DCL_UNORDERED_ACCESS_VIEW_TYPED
        | D3D11_SB_OPCODE_DCL_UNORDERED_ACCESS_VIEW_RAW
        | D3D11_SB_OPCODE_DCL_UNORDERED_ACCESS_VIEW_STRUCTURED
        | D3D11_SB_OPCODE_DCL_THREAD_GROUP_SHARED_MEMORY_RAW
        | D3D11_SB_OPCODE_DCL_THREAD_GROUP_SHARED_MEMORY_STRUCTURED
        | D3D11_SB_OPCODE_DCL_RESOURCE_RAW
        | D3D11_SB_OPCODE_DCL_RESOURCE_STRUCTURED => Some(true),
        D3D10_SB_OPCODE_DCL_GS_OUTPUT_PRIMITIVE_TOPOLOGY
        | D3D10_SB_OPCODE_DCL_GS_INPUT_PRIMITIVE
        | D3D10_SB_OPCODE_DCL_MAX_OUTPUT_VERTEX_COUNT
        | D3D10_SB_OPCODE_DCL_TEMPS
        | D3D10_SB_OPCODE_DCL_INDEXABLE_TEMP
        | D3D10_SB_OPCODE_DCL_GLOBAL_FLAGS
        | D3D11_SB_OPCODE_DCL_FUNCTION_BODY
        | D3D11_SB_OPCODE_DCL_FUNCTION_TABLE
        | D3D11_SB_OPCODE_DCL_INTERFACE
        | D3D11_SB_OPCODE_DCL_INPUT_CONTROL_POINT_COUNT
        | D3D11_SB_OPCODE_DCL_OUTPUT_CONTROL_POINT_COUNT
        | D3D11_SB_OPCODE_DCL_TESS_DOMAIN
        | D3D11_SB_OPCODE_DCL_TESS_PARTITIONING
        | D3D11_SB_OPCODE_DCL_TESS_OUTPUT_PRIMITIVE
        | D3D11_SB_OPCODE_DCL_HS_MAX_TESSFACTOR
        | D3D11_SB_OPCODE_DCL_HS_FORK_PHASE_INSTANCE_COUNT
        | D3D11_SB_OPCODE_DCL_HS_JOIN_PHASE_INSTANCE_COUNT
        | D3D11_SB_OPCODE_DCL_THREAD_GROUP
        | D3D11_SB_OPCODE_DCL_GS_INSTANCE_COUNT => Some(false),
        _ => None,
    }
}
